    #[must_use]
    pub fn stack_axis(&self) -> Option<crate::stack::LazyStackAxis> {
        let layout: &dyn Layout = match self.layout.as_ref().downcast_ref::<DirectionalLayout>() {
            Some(direction) => direction.inner.as_ref(),
            None => self.layout.as_ref(),
        };
        crate::stack::lazy_stack_axis(layout)
    }
