fn slider_node(&mut self, config: Native<SliderConfig>, parent: u32) -> u32 {
    let config = config.into_inner();
    let label = config.label.accessibility_label();
    let id = self.emit_leaf(component_type::SLIDER, label, parent);

    let (min, max) = (*config.range.start(), *config.range.end());
    self.builder.set_property(id, property_id::MIN_VALUE, value_type::F32, (min as f32).to_bits());
    self.builder.set_property(id, property_id::MAX_VALUE, value_type::F32, (max as f32).to_bits());

    let value: Computed<u32> = config.value.map(|v| (v as f32).to_bits()).computed();
    self.builder.set_property(id, property_id::VALUE, value_type::F32, value.get());
    self.reactive.push(Reactive::Property {
        node: id,
        property: property_id::VALUE,
        value_type: value_type::F32,
        value,
    });

    self.values.borrow_mut().insert(id, config.value);
    id
}
